// @ts-strict-ignore
import type { IGatsbyImageData } from "gatsby-plugin-image";
import Link from "@/core/components/primitives/link/link";
import styles from "./background-content-card.module.less";
import Label from "@/core/components/primitives/label/label";
import Icon, { IconName } from "@/core/components/primitives/icon/icon";

export type BackgroundContentCardProps = {
  imageData?: IGatsbyImageData;
  title?: string;
  shortDescription?: string;
  externalLink?: string;
  internalLink?: string;
  linkLabel?: string;
  /**@deprecated use icon instead */
  iconClass?: string;
  icon?: IconName;
  label?: string;
};
export const BackgroundContentCard = ({
  imageData,
  title,
  shortDescription,
  externalLink,
  internalLink,
  linkLabel,
  iconClass,
  icon,
  label,
}: BackgroundContentCardProps) => {
  const hasLink = externalLink || internalLink;

  return (
    <div className={styles.card}>
      {label && (
        <div className={styles.labelWrapper}>
          <Label title={label} />
        </div>
      )}
      {imageData && (
        <picture style={{ backgroundColor: imageData.backgroundColor }}>
          {imageData.images.sources.map((source) => (
            <source key={source.srcSet} {...source} />
          ))}
          <img {...imageData.images.fallback} alt={title || ""} loading="lazy" />
        </picture>
      )}
      <Link
        className={styles.cardOverlay}
        contentfulLink={!hasLink ? {} : undefined} // This is to make sure it is still rendered as an `a` tag even if no link is passed
        internalLink={internalLink}
        externalLink={externalLink}
        title={title}
        openInNewTab={!internalLink && !!externalLink}
      >
        {title && <h2>{title}</h2>}
        {shortDescription && <p>{shortDescription}</p>}
        {hasLink && linkLabel && (
          <span>
            {linkLabel} {iconClass && <i className={iconClass} />}{" "}
            {icon && <Icon className={styles.icon} name={icon} />}
          </span>
        )}
      </Link>
    </div>
  );
};
